exports.getAllFollowingPosts = async (req, res) => {
    const userId = req.user.id;
    let allFollowingPosts;

    try {
        allFollowingPosts = await User.findById(userId).select('following').populate({
            path: 'following',
            populate: {
                path: 'posts',
                model: 'Post'
            }
        });

        // Fetch all users with a public account
        const publicUsers = await User.find({ account: 'Public' }).populate({
            path: 'posts',
            model: 'Post'
        });

        // Combine both the results
        const combinedPosts = [
            ...allFollowingPosts.following,
            ...publicUsers
        ];

        // Remove duplicates
        const uniquePosts = Array.from(
            new Map(combinedPosts.map(post => [post.toString(), post]))
                .values()
        );

        res.status(200).json(uniquePosts)
    } catch (err) {
        res.status(500).json({ message: err.message });
    }
}

